window.products.push({"id":675664,"name":"Softball Glass Sports Ornament","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/51s8j9zIfDL._AC_SL1024_.jpg","description":"Softball is a game for highly competitive professionals and amateurs. The game was created in 1887 and was first called indoor baseball, mush ball, and even kitten ball because it was played by women. Today s game is played in nearly every American city and is growing in popularity around the world. 3\"","images":["https://m.media-amazon.com/images/I/51s8j9zIfDL._AC_SL1024_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Unknown","source_asin":"B081LGNDFH","category_path":"Home & Kitchen"},"sku":"BM-675664","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B081LGNDFH","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B081LGNDFH","price_pending":true,"merchant_ready":false});
